                .discard_superseded_present(OBJECT, FrameId(41), BufferId(11), 5, 7, 8,)
                .unwrap(),
            DenialMessage::BufferReleased {
                object: OBJECT,
                frame: FrameId(41),
                buffer: BufferId(11),
                release_point: 8,
